def posterior(prior, sens, fpr):
    evidence = sens * prior + fpr * (1 - prior)
    return sens * prior / evidence

def update_all(prior, results, sens, fpr):
    belief = prior
    for positive in results:
        l1, l0 = (sens, fpr) if positive else (1 - sens, 1 - fpr)
        belief = l1 * belief / (l1 * belief + l0 * (1 - belief))
    return belief
